import"./chunk-2NFLSA4Y.js";var t={totalInternalReflection:{param:{angle:"Angle of incidence",n1:"Medium 1 \xB7 refractive index",n2:"Medium 2 \xB7 refractive index",wavelength:"Vacuum wavelength",timeStep:"Time step",animationSpeed:"Marker speed scale"},hint:{angle:"Measured from the dashed normal, not from the boundary.",index:"Choose a material preset or enter an index. A larger n means a lower light speed.",wavelength:"The medium wavelength is \u03BB\u2080/n. Indices are fixed here, so changing wavelength does not change the ray angle.",animationSpeed:"Controls the slowed marker only. Its speeds keep the physical ratio v\u2082/v\u2081 = n\u2081/n\u2082."},preset:{angle0:"0\xB0 \xB7 normal",angle30:"30\xB0",angle60:"60\xB0",air:"Air \xB7 1.00",water:"Water \xB7 1.33",glass:"Glass \xB7 1.50",diamond:"Diamond \xB7 2.42",w450:"450 nm",w550:"550 nm",w650:"650 nm"},measure:{incidence:"Angle of incidence",refraction:"Angle of refraction",bend:"Bending toward normal (\u03B8\u2081 \u2212 \u03B8\u2082)",speed1:"Light speed in medium 1",speed2:"Light speed in medium 2",wavelength1:"Wavelength in medium 1",wavelength2:"Transmitted wavelength",snell1:"n\u2081 sin \u03B8\u2081",snell2:"n\u2082 sin \u03B8\u2082",rayHeight:"Marker height",critical:"Critical angle (\u2014 when n\u2081 \u2264 n\u2082)",margin:"Incidence minus critical angle"},view:{toward:"Bends toward the normal",away:"Bends away from the normal",straightThrough:"No change in direction",tir:"Total internal reflection",grazing:"Critical angle \xB7 along the boundary",medium1:"Medium 1",medium2:"Medium 2",incident:"Incident",refracted:"Refracted",noTransmission:"No transmitted ray",notice:"Schematic \xB7 slowed marker \xB7 brightness is not intensity",directions:"Direction arrows",normal:"Normal to the boundary",angles:"Angle arcs",reference:"Straight-line reference",critical:"Critical angle",noCritical:"No critical angle: n\u2081 \u2264 n\u2082",reflected:"Reflected"},graph:{height:"Marker height vs animation time"},theory:{concept:"[[Total internal reflection is the complete reflection of light back into an optically denser medium when it meets the boundary with a less dense one (n\u2081 > n\u2082) at an angle larger than the critical angle.]] As the angle of incidence grows, the refracted ray bends further from the normal; at the critical angle \u03B8c = arcsin(n\u2082/n\u2081) it runs along the boundary, and beyond it no light passes into the second medium at all. From glass into air the critical angle is about 42\xB0."},section:{critical:{title:"When refraction stops",text:"Going from larger n to smaller n, the transmitted angle reaches 90\xB0 at the critical angle. [[Above it there is total internal reflection: no propagating transmitted ray, so its angle and wavelength show a dash.]] At the critical angle the drawn boundary ray is a limiting direction, not a claim about transmitted power."},uses:{title:"Where it is used",text:"[[Total internal reflection keeps light inside a transparent material almost without loss.]] An optical fibre is a thin glass core surrounded by a layer with a smaller refractive index: the light reflects from the boundary again and again and travels for many kilometres, carrying internet and telephone signals. Prisms in binoculars and periscopes turn light through 90\xB0 or 180\xB0 more efficiently than mirrors. A diamond sparkles because its critical angle is only about 24\xB0: much of the light that enters it is reflected inside several times before it comes out."}},formula:{snell:"Snell\u2019s law",speed:"Refractive index and speed",wavelength:"Wavelength and constant frequency",critical:"Critical angle"},variable:{index:"Refractive indices of the media",angles:"Angles to the normal",speed:"Light speed in a medium and in vacuum",wavelength:"Vacuum and medium wavelengths",frequency:"Frequency",critical:"Critical angle"},assumption:{media:"Two homogeneous, isotropic, non-dispersive transparent media. Preset indices are approximate: air is treated as n = 1; real values depend on wavelength, temperature and material.",intensity:"Only ray directions are modelled. Partial reflection, Fresnel intensities, polarisation, absorption and evanescent fields are omitted. Line brightness does not represent energy.",boundary:"One flat, stationary boundary and geometrical optics; diffraction and finite beam width are neglected. The drawing is schematic, not a scale diagram of a real apparatus.",animation:"Dots are slowed teaching markers, not photons. Both media use the same slowdown so relative speeds are correct. The marker repeats after two equal diagram path lengths; time and graph coordinates describe this teaching animation."},challenge:{normal:{title:"Go straight through",description:"Make both angles zero at the boundary.",hint:"Set the angle of incidence to 0\xB0."},toward:{title:"Bend toward the normal",description:"Make the refracted angle at least 10\xB0 smaller than the incident angle.",hint:"Try air to glass at 45\xB0 or more."},away:{title:"Bend away from the normal",description:"Make the refracted angle at least 10\xB0 larger, while keeping a transmitted ray.",hint:"Try glass to air at 30\xB0. A larger angle can cause total reflection."},unchanged:{title:"Hide the optical boundary",description:"Keep the direction unchanged with an incident angle of at least 30\xB0.",hint:"Choose equal indices in both media."},tir:{title:"Keep light in medium 1",description:"Create total internal reflection.",hint:"Try glass to air at 60\xB0."},wavelength:{title:"Halve the wavelength",description:"Obtain a nonzero refracted angle and a transmitted wavelength half that in medium 1.",hint:"Make n\u2082 twice n\u2081, for example 2.00 and 1.00."}}}},n={sim:t};export{n as default,t as sim};
